// ParseMajor reads an amount a person typed in major units ("12.50", "7") and returns it in minor units. The number may
// have at most the currency's decimals ("12.5" USD is 1250, "7" KWD is 7000); JPY takes no decimal point at all.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	s = strings.TrimSpace(s)
	whole, frac, hasDot := strings.Cut(s, ".")
	d := c.MinorUnits()
	if whole == "" || (hasDot && (frac == "" || len(frac) > d)) {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < d {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people, with the currency's symbol and decimals: "$1,234.50", "¥1,000", "-KWD 0.005".
func Format(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + symbols[c] + group(whole) + frac
}

// FormatMajor renders an amount in major units, with the currency's decimals and no thousands separator: "12.50",
// "1000", "1.250". It is the form people type, so ParseMajor reads it back.
func FormatMajor(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + strconv.FormatInt(whole, 10) + frac
}

// split separates an amount into its sign, its whole major units and its fraction, which includes the point ("" for a
// currency with no decimals).
func split(amount int64, c Currency) (sign string, whole int64, frac string) {
	if amount < 0 {
		sign, amount = "-", -amount
	}
	d := c.MinorUnits()
	pow := int64(1)
	for i := 0; i < d; i++ {
		pow *= 10
	}
	whole = amount / pow
	if d == 0 {
		return sign, whole, ""
	}
	return sign, whole, fmt.Sprintf(".%0*d", d, amount%pow)
}

