func TestPlanPricesByCurrency(t *testing.T) {
	e := apitest.New(t)
	for _, c := range []struct {
		currency, price, wantAmount, wantPrice, wantFormatted string
		wantUnits                                             int64
	}{
		{"JPY", "1000", "1000", "1000", "¥1,000", 1000},
		{"KWD", "1.250", "1.250", "1.250", "KWD 1.250", 1250},
		{"KWD", "7", "7.000", "7", "KWD 7.000", 7000},
		{"USD", "1234.5", "1234.50", "1234.50", "$1,234.50", 123450},
	} {
		var p struct {
			store.Plan
			Price          string `json:"price"`
			PriceFormatted string `json:"price_formatted"`
		}
		e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "Team", "currency": c.currency, "price": c.price, "interval": "month"}, &p)
		if p.UnitAmount != c.wantUnits || p.Price != c.wantPrice || p.PriceFormatted != c.wantFormatted {
			t.Fatalf("%s %s: plan = %+v", c.currency, c.price, p)
		}
	}
	for _, bad := range []map[string]any{
		{"name": "X", "currency": "JPY", "price": "1000.5", "interval": "month"},
		{"name": "X", "currency": "JPY", "price": "1000.", "interval": "month"},
		{"name": "X", "currency": "KWD", "price": "1.2345", "interval": "month"},
		{"name": "X", "currency": "USD", "price": "1.234", "interval": "month"},
	} {
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_amount" {
			t.Fatalf("%v: %s", bad, r)
		}
	}
	var list struct {
		Items []struct {
			Price          string `json:"price"`
			PriceFormatted string `json:"price_formatted"`
		} `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/plans", e.Acme.Key, nil, &list)
	if len(list.Items) == 0 {
		t.Fatal("no plans listed")
	}
}

