69	// Format renders an amount for people, with the currency's symbol and decimals: "$1,234.50", "¥1,000", "-KWD 0.005".
70	func Format(amount int64, c Currency) string {
71		sign, whole, frac := split(amount, c)
72		return sign + symbols[c] + group(whole) + frac
73	}
74	
75	// FormatMajor renders an amount in major units, with the currency's decimals and no thousands separator: "12.50",
76	// "1000", "1.250". It is the form people type, so ParseMajor reads it back.
77	func FormatMajor(amount int64, c Currency) string {
78		sign, whole, frac := split(amount, c)
79		return sign + strconv.FormatInt(whole, 10) + frac
80	}
81	
82	// split separates an amount into its sign, its whole major units and its fraction, which includes the point ("" for a
83	// currency with no decimals).
84	func split(amount int64, c Currency) (sign string, whole int64, frac string) {
85		if amount < 0 {
86			sign, amount = "-", -amount
87		}
88		d := c.MinorUnits()
89		pow := int64(1)
90		for i := 0; i < d; i++ {
91			pow *= 10
92		}
93		whole = amount / pow
94		if d == 0 {
95			return sign, whole, ""
96		}
97		return sign, whole, fmt.Sprintf(".%0*d", d, amount%pow)
98	}
99	
100	// group writes n with a comma between each group of three digits.
101	func group(n int64) string {
102		s := strconv.FormatInt(n, 10)
103		var b strings.Builder
104		for i, r := range s {
105			if i > 0 && (len(s)-i)%3 == 0 {
106				b.WriteByte(',')
107			}
108			b.WriteRune(r)
109		}
110		return b.String()
111	}
112	
113	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
114	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
115	
116	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
117	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
118	
119	// divRound divides and rounds half away from zero.
120	func divRound(num, den int64) int64 {
121		if (num < 0) != (den < 0) {
122			return -((abs(num) + abs(den)/2) / abs(den))
123		}
124		return (abs(num) + abs(den)/2) / abs(den)
125	}
126	
127	func abs(v int64) int64 {
128		if v < 0 {
129			return -v
130		}
131		return v
132	}
